import json
from pathlib import Path
ROOT=Path(__file__).parent
source={'synthetic':True,'assumption':'51 endpoint attachments: one logical switch interface per unit; not a complete real network inventory. Add interface records as required.','vlans':{'1':'Default','55':'Science data','77':'Management','155':'Science data — local A','255':'Science data — local B'},'interfaces':[],'translations':[]}
for group,count in [('VCCU',24),('FSPU',27)]:
    for n in range(1,count+1):
        sw='SW-A' if group=='VCCU' else 'SW-B'; iface=f'Eth1/{n:02d}'
        direct=n<=16 if group=='VCCU' else n<=19
        translated=17<=n<=20 if group=='VCCU' else 20<=n<=24
        allowed=[1,55] if direct else [1,155 if group=='VCCU' else 255] if translated else [1,77]
        source['interfaces'].append({'unit_group':group,'unit':f'{group} {n:02d}','switch':sw,'interface':iface,'allowed_vlans':allowed})
        if (group=='VCCU' and n in (17,18)) or (group=='FSPU' and n in (20,21,22)):
            source['translations'].append({'switch':sw,'interface':iface,'selected_vlan':55,'local_vlan':155 if group=='VCCU' else 255})
(ROOT/'mock-network.json').write_text(json.dumps(source,indent=2)+'\n')
DS={'type':'prometheus','uid':'server-health-demo-prometheus'}
def target(expr):return {'datasource':DS,'expr':expr,'refId':'A','instant':True,'range':False,'format':'table'}
def stat(id,title,expr,x,w,color='blue'):
    return {'id':id,'title':title,'type':'stat','datasource':DS,'gridPos':{'x':x,'y':2,'w':w,'h':3},'targets':[target(expr)],'fieldConfig':{'defaults':{'color':{'mode':'fixed','fixedColor':color},'decimals':0,'noValue':'0'},'overrides':[]},'options':{'reduceOptions':{'calcs':['lastNotNull'],'fields':'','values':False},'orientation':'horizontal','textMode':'value_and_name','colorMode':'value','graphMode':'none','justifyMode':'auto'}}
panels=[{'id':1,'title':'Network VLAN viewer · DEMO','type':'text','gridPos':{'x':0,'y':0,'w':24,'h':2},'options':{'mode':'markdown','content':'**Select a VLAN above.** VCC units on the left · FSP units on the right. Green = directly allowed; blue = explicit translation on that exact switch interface.\n\n**Synthetic configuration** · 51 endpoint attachments · one interface per unit for this demo.'}},stat(2,'Interfaces in demo inventory','count(vlan_interface_inventory)',0,6),stat(3,'Matching selected VLAN','count(vlan_interface_match{selected_vlan="$vlan"}) or vector(0)',6,6),stat(4,'Directly allowed','count(vlan_interface_match{selected_vlan="$vlan",match_kind="direct"}) or vector(0)',12,6,'green'),stat(5,'Explicitly translated','count(vlan_interface_match{selected_vlan="$vlan",match_kind="translated"}) or vector(0)',18,6,'blue')]
for id,group,title,x in [(10,'VCCU','VCC units · allowed interfaces',0),(11,'FSPU','FSP units · allowed interfaces',12)]:
    renames={'unit':'Unit','attachment':'Switch / interface','allowed_vlans':'Allowed VLANs','translation':'Route','Value':'Match'}
    hide={k:True for k in ['Time','__name__','actual_vlan','allowed_names','instance','job','match_kind','selected_vlan','switch','interface','unit_group']}
    widths={'Unit':95,'Switch / interface':155,'Allowed VLANs':110,'Route':110,'Match':110}
    overrides=[{'matcher':{'id':'byName','options':name},'properties':[{'id':'custom.width','value':width}]} for name,width in widths.items()]
    overrides +=[{'matcher':{'id':'byName','options':'Match'},'properties':[{'id':'custom.cellOptions','value':{'type':'color-background','mode':'basic','applyToRow':True}},{'id':'mappings','value':[{'type':'value','options':{'0':{'text':'Direct','color':'green','index':0},'1':{'text':'Translated','color':'blue','index':1}}}]}]}]
    panels.append({'id':id,'title':title,'description':'Only interfaces explicitly allowing the selected VLAN, or having a configured forward translation on that exact switch/interface to an allowed local VLAN. One row per matching interface. Full allowed VLAN names are available in Inspect → Data.','type':'table','datasource':DS,'gridPos':{'x':x,'y':5,'w':12,'h':20},'targets':[target(f'vlan_interface_match{{selected_vlan="$vlan",unit_group="{group}"}}')],'transformations':[{'id':'organize','options':{'excludeByName':hide,'indexByName':{'unit':0,'attachment':1,'allowed_vlans':2,'translation':3,'Value':4},'renameByName':renames}},{'id':'sortBy','options':{'fields':{},'sort':[{'field':'Unit','desc':False}]}}],'fieldConfig':{'defaults':{'custom':{'align':'left','cellOptions':{'type':'auto'},'filterable':False,'inspect':True},'noValue':'—','color':{'mode':'thresholds'},'thresholds':{'mode':'absolute','steps':[{'color':'green','value':None},{'color':'blue','value':1}]}},'overrides':overrides},'options':{'showHeader':True,'cellHeight':'sm','footer':{'show':False},'sortBy':[{'displayName':'Unit','desc':False}]}})
panels.append({'id':20,'title':'How this filter works','type':'text','gridPos':{'x':0,'y':25,'w':24,'h':3},'options':{'mode':'markdown','content':'**VLAN 55 demo:** 35 direct interfaces + 5 explicitly translated interfaces = 40 matches. Blue rows show **55 → 155** or **55 → 255**. Other ports allowing 155 or 255 remain excluded unless their exact switch/interface has a rule.\n\nTranslations are **directed and interface-scoped**: no automatic reverse mapping, no multi-hop inference. A direct match takes precedence. VLAN names: **1 Default · 55 Science data · 77 Management · 155 Science data — local A · 255 Science data — local B**.'}})
dashboard={'uid':'vlan-net-viewer-demo','title':'Network VLAN viewer · VCC units / FSP units','schemaVersion':41,'version':1,'editable':True,'tags':['demo','synthetic','VLAN','VCCU','FSPU'],'timezone':'browser','time':{'from':'now-15m','to':'now'},'refresh':'10s','panels':panels,'templating':{'list':[{'name':'vlan','label':'VLAN','type':'query','datasource':DS,'definition':'label_values(vlan_catalog_info, vlan)','query':{'query':'label_values(vlan_catalog_info, vlan)','refId':'StandardVariableQuery'},'refresh':1,'sort':3,'multi':False,'includeAll':False,'current':{'text':'55','value':'55'},'options':[]} ]}}
(ROOT/'grafana/dashboards/vlan-net-viewer.json').write_text(json.dumps(dashboard,indent=2)+'\n')
(ROOT/'grafana/provisioning/dashboard-provider.yaml').write_text('apiVersion: 1\nproviders:\n  - name: vlan-net-viewer-demo\n    orgId: 1\n    type: file\n    disableDeletion: true\n    allowUiUpdates: true\n    updateIntervalSeconds: 10\n    options:\n      path: /var/lib/grafana/vlan-net-viewer-demo\n')
print('Wrote 51 interface records, explicit translations and native Grafana dashboard.')
